WITH recent_inventory AS (SELECT * FROM inventory WHERE store_id IN (4, 5) AND product_id IN (5, 6, 9)), LastRestockCohortSummary AS (SELECT CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END AS last_restock_cohort, MIN(last_restock) AS first_last_restock FROM recent_inventory GROUP BY CASE WHEN YEAR(last_restock) < 2024 THEN 'before_2024' WHEN YEAR(last_restock) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT last_restock_cohort, first_last_restock FROM LastRestockCohortSummary ORDER BY first_last_restock DESC;
